contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        uint256 cEthBefore = address(c).balance;

        // The caller's entire recorded balance is exactly `amount`, since the test
        // contract has deposited only this one positive amount and has no other
        // source of recorded balance in this run. Withdrawing twice that amount
        // is therefore strictly larger than the caller's whole balance.
        bool reverted;
        c.withdraw(amount * 2); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Rule: the over-balance withdrawal must revert and leave the contract's
        // Ether balance unchanged. The caller's recorded balance is restored to
        // its pre-withdrawal state, which is observable as a refund to be able
        // to withdraw exactly `amount` afterwards (refund zeroes it).
        assert(reverted && address(c).balance == cEthBefore);
    }

    receive() external payable {}
}

